export type TextKey = string;

type ReplaceParams = Record<string, string | number>;

const replaceParams = (value: string, params?: ReplaceParams): string => {
  if (!params) return value;
  return value.replace(/\{(\w+)\}/g, (match, name) => {
    const replacement = params[name];
    return replacement === undefined ? match : String(replacement);
  });
};

export const t = (
  key: TextKey,
  primary: UiLanguage,
  secondary: UiLanguage,
  params?: ReplaceParams,
): string => {
  const entry = TEXT_MAP[key];
  if (!entry) return "";
  const primaryRaw = entry[primary] ?? "";
  const secondaryRaw = entry[secondary] ?? "";
  const primaryTrimmed = primaryRaw.trim();
  const secondaryTrimmed = secondaryRaw.trim();
  const resolved = primaryTrimmed ? primaryRaw : secondaryTrimmed ? secondaryRaw : "";
  return resolved ? replaceParams(resolved, params) : "";
};

